function addWebsite(entry,share=false){saveProfile();const next=structuredClone(profileState),id=next.active;next.profiles[id].engines.push(structuredClone(entry));if(share){const other=id==='domestic'?'international':'domestic';next.profiles[other].engines.push({...structuredClone(entry),id:crypto.randomUUID()});}commitState(next);cfg=profileConfig(next);}

const hostMatch=(r,h)=>{const m=h.match(r.host);return!!m&&m[0]===h;};
function shareId(u){return u.searchParams.get('code')||u.pathname.match(/\/s\/([^/?#]+)/)?.[1]||u.pathname.replace(/\/$/,'').split('/').pop()||u.searchParams.get('linkID')||'';}
