function visible(n){return !!n?.getClientRects?.().length&&!n.disabled;}
function fillField(field,value){const w=field.ownerDocument.defaultView,last=field.value;if(field.tagName==='INPUT'||field.tagName==='TEXTAREA'){const C=field.tagName==='INPUT'?w.HTMLInputElement:w.HTMLTextAreaElement;Object.getOwnPropertyDescriptor(C.prototype,'value').set.call(field,value);}else field.textContent=value;field._valueTracker?.setValue(last);field.dispatchEvent(new w.Event('input',{bubbles:true}));field.dispatchEvent(new w.Event('change',{bubbles:true}));}
function pendingCode(){const raw=new URL(entryURL);for(const[id,r]of Object.entries(PAN)){if(!hostMatch(r,raw.hostname))continue;const q=raw.searchParams.get('pwd')||raw.searchParams.get('p'),hash=raw.hash.slice(1);if(q&&/^[A-Za-z0-9]{3,8}$/.test(q))return{id,r,code:q};if(/^[A-Za-z0-9]{3,8}$/.test(hash))return{id,r,code:hash};const records=get('baguaCloudPending',[]);let ref;try{ref=new URL(document.referrer);}catch{}const current=shareId(raw);const record=records.find(x=>x.id===id&&Date.now()-x.time<180000&&(x.share&&x.share===current||x.host===raw.hostname&&x.path===raw.pathname||IS_FRAME&&ref&&x.host===ref.hostname&&x.path===ref.pathname));if(record)return{id,r,code:record.code,record};}return null;}
function startCloudFill(){const item=pendingCode();if(!item)return;let tries=0;const timer=setInterval(()=>{if(++tries>60){clearInterval(timer);if(!IS_FRAME)toast('未找到'+item.r.name+'提取码输入框，请手动输入：'+item.code);return;}const docs=[document];for(const f of document.querySelectorAll('iframe'))try{if(f.contentDocument)docs.push(f.contentDocument);}catch{}let field;for(const doc of docs){for(const selector of item.r.input||[]){try{field=[...doc.querySelectorAll(selector)].find(visible);}catch{}if(field)break;}if(field)break;}if(!field)return;try{fillField(field,item.code);clearInterval(timer);if(!IS_FRAME)toast('已填写'+item.r.name+'提取码，请确认后进入');}catch{}},650);}
