const NS='http://www.w3.org/2000/svg';const svg=(tag,attrs,p)=>{const n=document.createElementNS(NS,tag);for(const[k,v]of Object.entries(attrs||{}))n.setAttribute(k,String(v));p?.append(n);return n;};
const polar=(r,a)=>[190+r*Math.cos(a*Math.PI/180),190+r*Math.sin(a*Math.PI/180)];
function wheelRingAtRadius(r,gap=false){return gap?(r>=34&&r<=103?'Inner':r>=114&&r<=178?'Outer':null):(r>=34&&r<109?'Inner':r>=109&&r<=178?'Outer':null);}
