function direction(dx,dy){return Math.abs(dx)>Math.abs(dy)?dx>0?1:3:dy>0?2:0;}
const DIRECTION=['上','右','下','左'];

function wheelLabel(group,ring,i,a,id,color){const text=(x,y,value,size=14)=>{const n=svg('text',{x,y,fill:color,'text-anchor':'middle'},group);n.style.fontFamily='Arial,"Microsoft YaHei",sans-serif';n.style.fontSize=size+'px';n.style.fontWeight='600';n.textContent=value;};if(ring==='Outer'&&(i===1||i===3)){const raw=Array.from(a.name),chars=raw.length>8?[...raw.slice(0,7),'…']:raw;chars.forEach((ch,j)=>text(190+(i===1?147:-147),190-(chars.length-1)*17/2+5+j*17,ch));return;}const point=polar(ring==='Inner'?70:147,-90+i*90),limit=ring==='Inner'&&(i===1||i===3)?58:ring==='Inner'?100:112,lines=[];let line='',width=0;for(const ch of Array.from(a.name)){const cw=/[\x00-\xff]/.test(ch)?8:14;if(width+cw>limit&&line){lines.push(line);line='';width=0;}line+=ch;width+=cw;}if(line)lines.push(line);if(lines.length>2){lines.length=2;lines[1]=lines[1].slice(0,-1)+'…';}const symbol=id!=='ocr'&&a.symbol;if(symbol)text(point[0],point[1]-(ring==='Outer'?10:13),symbol,19);const first=symbol?(lines.length>1?7:13):(lines.length>1?-2:5);lines.forEach((value,j)=>text(point[0],point[1]+first+j*17,value));}

function drawWheel(p,type,onPick,d=null,preview=false){const con=el('div',undefined,p);con.className='wheel'+(preview?' preview':'');const drawing=svg('svg',{width:380,height:380,viewBox:'0 0 380 380'},con),paths=[];svg('circle',{cx:190,cy:190,r:178,fill:'#e9edf2'},drawing);for(const[ring,r1,r2,labelR]of ([['Outer',109,178,147],['Inner',25,109,73]]))for(let i=0;i<4;i++){const id=cfg[type+ring][i],a=action(id,d||{kind:type,value:'',shareText:''}),g=svg('g',{class:'wb'},drawing),dark=(i%2===0)!==(ring==='Inner'),path=svg('path',{d:sectorPath(r1,r2,i),fill:dark?'#454545':'#fff',class:'sector'},g);const color=dark?'#fff':'#25313d';wheelLabel(g,ring,i,a,id,color);svg('title',{},g).textContent=a.name;path.onclick=()=>onPick(ring,i,a);paths.push({ring,i,path,a,g});if(preview){const pivot=polar(ring==='Inner'?70:147,-90+i*90);g.onpointerenter=()=>liftWheel(g,true,pivot[0],pivot[1],false);g.onpointerleave=()=>liftWheel(g,false,pivot[0],pivot[1],false);}}const cg=svg('g',{class:'wc'},drawing);const center=svg('circle',{cx:190,cy:190,r:25,fill:'#fff',stroke:'#b6c5d3',class:'center'},cg);const image=svg('image',{href:"data:image/svg+xml;base64,",x:169,y:169,width:42,height:42,preserveAspectRatio:'xMidYMid meet'},cg);image.style.pointerEvents='none';cg.onpointerenter=()=>liftWheel(cg,true,190,190,true);cg.onpointerleave=()=>liftWheel(cg,false,190,190,true);if(!preview)center.onclick=closeWheel;else{const z=Math.min(1,cfg.wheelScale/100,(innerWidth-12)/380,(innerHeight-12)/380);con.classList.add('live-wheel-preview');drawing.style.cssText='width:380px!important;height:380px!important;max-width:none!important;transform-origin:top left;transform:scale('+z+')';}return{con,paths,cg};}
function showWheel(d,x,y){closeBox();closeWheel();const type=d.kind==='image'?'image':d.kind==='link'?'link':'text',r=drawWheel(root,type,(_,__,a)=>{closeWheel();safe(a.run);},d),scale=Math.min(cfg.wheelScale/100,(innerWidth-12)/380,(innerHeight-12)/380),left=Math.max(6,Math.min(innerWidth-380*scale-6,x-190*scale)),top=Math.max(6,Math.min(innerHeight-380*scale-6,y-190*scale));wheel=r.con;wheel.style.cssText=`left:${left}px;top:${top}px;transform:scale(${scale})`;wheelInfo={...r,scale,left,top};}
function selectWheel(x,y){if(!wheelInfo)return null;const dx=(x-wheelInfo.left)/wheelInfo.scale-190,dy=(y-wheelInfo.top)/wheelInfo.scale-190,r=Math.hypot(dx,dy),ring=wheelRingAtRadius(r,cfg.wheelGap),i=direction(dx,dy);liftWheel(wheelInfo.cg,r<=25,190,190,true);let result=null;for(const p of wheelInfo.paths){const yes=p.ring===ring&&p.i===i;const pivot=polar(p.ring==='Inner'?70:147,-90+p.i*90);liftWheel(p.g,yes,pivot[0],pivot[1],false);if(yes)result=p.a;}return result;}
function hint(text,x,y){let n=root.querySelector('.hint');if(!n){n=el('div',undefined,root);n.className='hint';}n.textContent=text;n.style.left=Math.max(6,Math.min(innerWidth-240,x+18))+'px';n.style.top=Math.max(6,Math.min(innerHeight-40,y+18))+'px';}const noHint=()=>root.querySelector('.hint')?.remove();
function fileDB(mode,key,value){key='epoch-'+get('directoryEpoch',0)+':'+key;return new Promise((resolve,reject)=>{const req=indexedDB.open('baguaPublicHandlesV1',1);req.onupgradeneeded=()=>req.result.createObjectStore('handles');req.onerror=()=>reject(req.error);req.onsuccess=()=>{const db=req.result,tx=db.transaction('handles',mode),os=tx.objectStore('handles');let result;const r=mode==='readonly'?os.get(key):value===null?os.delete(key):os.put(value,key);r.onsuccess=()=>result=r.result;tx.oncomplete=()=>{db.close();resolve(result);};tx.onerror=()=>{db.close();reject(tx.error);};};});}
let downloadDir=null;
try{recordDir=await fileDB('readonly','records');imageDir=await fileDB('readonly','images');downloadDir=await fileDB('readonly','downloads');}catch{}
async function permission(h,ask=false){if(!h)return false;const o={mode:'readwrite'};return await h.queryPermission(o)==='granted'||ask&&await h.requestPermission(o)==='granted';}
const pad=n=>String(n).padStart(2,'0');const monthKey=t=>{const d=new Date(t);return`${d.getFullYear()}-${pad(d.getMonth()+1)}`;};const hourKey=t=>{const d=new Date(t);return`${monthKey(t)}-${pad(d.getDate())} ${pad(d.getHours())}时`;};const dayKey=t=>hourKey(t).slice(0,10);

const RECORD_SEPARATOR='\n\n────────────────────\n\n';
const EMPTY_BUFFER={rev:0,items:[],txn:null};
const recordId=()=>globalThis.crypto?.randomUUID?.()||Date.now().toString(36)+'-'+Math.random().toString(36).slice(2);
function getBuffer(){const s=get('record-buffer-v1',EMPTY_BUFFER);if(!s||!Array.isArray(s.items)||s.items.length>10||!s.items.every(x=>x&&typeof x.id==='string'&&typeof x.text==='string'&&Number.isFinite(x.time)&&typeof x.saved==='boolean'))throw Error('暂存记录格式异常，请先备份油猴数据');s.rev=Number.isFinite(s.rev)?s.rev:0;s.txn=s.txn||null;return s;}
const wait=ms=>new Promise(r=>setTimeout(r,ms));
async function withRecordLock(fn){const token=recordId(),start=Date.now();let heartbeat;while(Date.now()-start<12000){const now=Date.now(),current=get('record-lock',null);if(!current||current.until<now){put('record-lock',{token,until:now+45000});await wait(60+Math.floor(Math.random()*50));if(get('record-lock',null)?.token===token){const assert=()=>{if(get('record-lock',null)?.token!==token)throw Error('记录锁已失效，请重试');};heartbeat=setInterval(()=>{if(get('record-lock',null)?.token===token)put('record-lock',{token,until:Date.now()+45000});},5000);try{return await fn(assert);}finally{clearInterval(heartbeat);if(get('record-lock',null)?.token===token)put('record-lock',null);}}}await wait(100);}throw Error('其他页面正在处理记录，请稍后重试');}
function storeBuffer(s,assert){assert();if(getBuffer().rev!==s.rev)throw Error('记录已被其他页面更新，请重试');s.rev++;put('record-buffer-v1',s);}

function recordStamp(time,filename=false){const d=new Date(time),date=d.getFullYear()+'-'+pad(d.getMonth()+1)+'-'+pad(d.getDate()),clock=[pad(d.getHours()),pad(d.getMinutes()),pad(d.getSeconds())].join(filename?'-':':');return date+(filename?'_':' ')+clock;}
function recordBatchText(items){return recordStamp(items[0].time)+'\r\n\r\n'+items.map(x=>x.text).join('\r\n\r\n')+'\r\n';}
function batchFilename(items){return '八卦搜索-记录-'+recordStamp(items[0].time,true)+'.txt';}
function unsavedRecords(s){return s.items.filter(x=>!x.saved).sort((a,b)=>a.time-b.time);}
function assertBatchTxn(s){if(s.txn&&s.txn.kind!=='batch-file-v1')throw Error('旧版有一批月度写入尚未完成。请先用旧版处理或备份；这些记录未被清除。');}
async function clearSavedBatch(s,assert){const ids=s.txn.ids;s.items=s.items.filter(x=>!ids.includes(x.id));s.txn=null;storeBuffer(s,assert);await fileDB('readwrite','batchFileHandle',null).catch(()=>{});}
async function saveBatchInside(s,assert,allowRetry=false){
 assertBatchTxn(s);const items=unsavedRecords(s);if(!items.length){if(s.items.length){s.items=[];storeBuffer(s,assert);}return 0;}
 if(!s.txn){if(cfg.recordMode==='custom'&&!recordDir)throw Error('请点击“更改位置”重新确认自定义记录文件夹');s.txn={kind:'batch-file-v1',id:recordId(),ids:items.map(x=>x.id),name:batchFilename(items),target:recordDir?'custom':'default',state:'ready'};storeBuffer(s,assert);}
 const tx=s.txn,batch=tx.ids.map(id=>s.items.find(x=>x.id===id));if(batch.some(x=>!x))throw Error('批次内容不完整，请先备份记录');const body='\ufeff'+recordBatchText(batch),blob=new Blob([body],{type:'text/plain;charset=utf-8'});
 if(tx.target==='default'){
 if(tx.state==='downloading'&&!allowRetry)throw Error('上次下载结果未确认，请在“查看记录”检查并手动保存');
 if(tx.state==='downloading'&&allowRetry&&!window.confirm('请先检查上次的下载文件。是否仍要重新保存这一批？'))return 0;
 tx.state='downloading';storeBuffer(s,assert);const url=URL.createObjectURL(blob);try{await startNativeDownload(url,defaultSavePath('records',tx.name));assert();await clearSavedBatch(s,assert);return batch.length;}catch(error){if(getBuffer().rev===s.rev){tx.state='ready';storeBuffer(s,assert);}throw Error('文件下载未完成：'+error.message+'；记录已保留');}finally{setTimeout(()=>URL.revokeObjectURL(url),60000);}
 }
 const dir=await targetDirectory('records');if(!dir)throw Error('自定义目录暂不可用，请点击“更改位置”重新确认');let h=await fileDB('readonly','batchFileHandle');
 if(h){const current=await dir.getFileHandle(tx.name);if(current.isSameEntry&&!await current.isSameEntry(h))throw Error('请恢复这批记录原来的保存目录');h=current;}
 else {let name=tx.name,i=1;while(true){try{await dir.getFileHandle(name);name=tx.name.replace(/\.txt$/,' ('+(++i)+').txt');}catch(error){if(error.name!=='NotFoundError')throw error;break;}if(i>1000)throw Error('同名文件过多，请更换记录目录');}tx.name=name;storeBuffer(s,assert);h=await dir.getFileHandle(name,{create:true});await fileDB('readwrite','batchFileHandle',h);}
 const f=await h.getFile();if(f.size>3*1024*1024)throw Error('目标文件已被修改，未覆盖');const old=await f.text();if(old.replace(/^\uFEFF/,'')===body.replace(/^\uFEFF/,'')){await clearSavedBatch(s,assert);return batch.length;}if(old.length)throw Error('目标文件已有其他内容，未覆盖；请检查文件');
 assert();const w=await h.createWritable();try{await w.write(blob);assert();await w.close();}catch(error){await w.abort().catch(()=>{});throw error;}if((await(await h.getFile()).text()).replace(/^\uFEFF/,'')!==body.replace(/^\uFEFF/,''))throw Error('写入校验未通过，记录仍然保留');await clearSavedBatch(s,assert);return batch.length;
}
async function flushRecords(allowRetry=false){return withRecordLock(async assert=>{const s=getBuffer(),count=await saveBatchInside(s,assert,allowRetry);toast(count?'已保存'+count+'条记录，列表已清空':'没有待保存的记录或本次操作已取消');});}
async function record(text){if(typeof text!=='string'||!text.trim())throw Error('没有可记录的文字');if(text.length>100000)throw Error('单条记录请少于10万字');let copied=true;try{await copy(text);}catch{copied=false;}let added=false;
 try{await withRecordLock(async assert=>{const s=getBuffer();assertBatchTxn(s);s.items=s.items.filter(x=>!x.saved);if(s.txn||s.items.length>=10)await saveBatchInside(s,assert);if(s.items.length>=10)throw Error('待保存记录已满，不能覆盖旧记录');s.items.push({id:recordId(),time:Date.now(),text,saved:false});storeBuffer(s,assert);added=true;if(s.items.length>=10){await saveBatchInside(s,assert);toast((copied?'已复制；':'复制失败；')+'已保存10条记录，列表已清空');}else toast((copied?'已复制；':'复制失败；')+'待保存 '+s.items.length+'/10 条');});}
 catch(error){if(added)toast('记录已暂存；保存未完成：'+error.message);else throw Error((copied?'已复制，但新记录未加入：':'新记录未加入：')+error.message);}
}
async function chooseRecordFolder(){if(!window.showDirectoryPicker)throw Error('请在支持选择文件夹的HTTPS网页操作');const h=await window.showDirectoryPicker({mode:'readwrite',startIn:'downloads',id:'bagua-record-folder'});await fileDB('readwrite','records',h);recordDir=h;cfg.recordMode='custom';persist();toast('已更改记录位置');}
function recordsUI(){const p=panel('查看记录','textmodal'),top=el('div',undefined,p);top.className='record-top';const summary=el('span','',top);const all=button(top,'全部复制',()=>{const items=unsavedRecords(getBuffer());if(!items.length)throw Error('没有可复制的记录');return copy(items.map(x=>x.text).join('\n\n'));});all.className='record-copy-all';const list=el('div',undefined,p);const save=button(p,'保存TXT',async()=>{try{await flushRecords(true);}finally{refresh();}});save.className='record-save-bottom';
 function refresh(){const state=getBuffer(),items=unsavedRecords(state);summary.textContent='待保存 '+items.length+'/10 条';list.replaceChildren();all.disabled=save.disabled=!items.length;if(items.length)el('div',recordStamp(items[0].time),list).className='muted record-first-time';for(const x of items){const row=el('div',undefined,list);row.className='record-entry';el('div',x.text,row).className='content';button(row,'复制',()=>copy(x.text));}if(!items.length)el('p','暂无待保存记录',list);if(state.txn&&state.txn.kind!=='batch-file-v1')el('p','旧版有一次未完成的月度写入，请先处理；记录仍然保留。',list).className='muted';}refresh();}

const SAVE_DIRS={records:'记录',images:'图片',downloads:'下载'};
function defaultSavePath(kind,name=''){return['八卦搜索',SAVE_DIRS[kind],name].filter(Boolean).join('/');}
function overrideFor(kind){return kind==='records'?recordDir:kind==='images'?imageDir:downloadDir;}
function assignOverride(kind,h){if(kind==='records')recordDir=h;else if(kind==='images')imageDir=h;else if(kind==='downloads')downloadDir=h;}
async function targetDirectory(kind){const h=overrideFor(kind);if(!h)return null;if(!await permission(h))throw Error(SAVE_DIRS[kind]+'位置暂不可用，请点击“更改位置”重新确认');return h;}
function targetDescription(kind){const h=overrideFor(kind);return h?'已选择：'+h.name:'浏览器下载目录／'+defaultSavePath(kind);}
async function chooseDirectory(kind){if(!SAVE_DIRS[kind])return;if(kind==='records'){await chooseRecordFolder();showSettings('records');return;}if(!window.showDirectoryPicker)throw Error('请在支持选择文件夹的HTTPS网页操作');const h=await window.showDirectoryPicker({mode:'readwrite'});await fileDB('readwrite',kind,h);assignOverride(kind,h);showSettings('records');}
async function resetDirectory(kind){if(!SAVE_DIRS[kind])return;if(kind==='records'&&getBuffer().txn)throw Error('请先完成或备份待保存批次，再恢复默认位置');await fileDB('readwrite',kind,null);assignOverride(kind,null);if(kind==='records'){cfg.recordMode='default';persist();}showSettings('records');}
