async function bingSession(){if(freeTranslationSession&&Date.now()-freeTranslationSession.time<1200000)return freeTranslationSession;const origin=profileState.active==='international'?'https://www.bing.com':'https://cn.bing.com';const r=await request(origin+'/translator'),session=parseBingSession(r.responseText);session.origin=origin;try{const url=new URL(r.finalUrl||session.origin);if(/(^|\.)bing\.com$/i.test(url.hostname))session.origin=url.origin;}catch{}return freeTranslationSession=session;}
const bingLanguage=code=>({zh:'zh-Hans','zh-CN':'zh-Hans','zh-TW':'zh-Hant',jp:'ja',kor:'ko',fra:'fr',spa:'es'})[code]||code;

