function imageName(url,type=''){let name;try{name=decodeURIComponent(new URL(url,location.href).pathname.split('/').pop()||'image');}catch{name='image';}name=name.replace(/[\\/:*?"<>|\x00-\x1f]/g,'_').slice(0,100);if(!/\.(png|jpe?g|webp|gif|bmp|avif|svg)$/i.test(name))name+='.'+({'image/png':'png','image/webp':'webp','image/gif':'gif','image/svg+xml':'svg'}[type]||'jpg');return Date.now()+'-'+name;}

