function downloadName(url){let name;try{name=decodeURIComponent(new URL(url).pathname.split('/').pop()||'download');}catch{name='download';}return name.replace(/[\\/:*?"<>|\x00-\x1f]/g,'_').slice(0,160)||'download';}
