function fwSettings(p){const v=discLayout(p);let active=0;v.range.value=fw.size;v.percent.textContent=fw.size+'%';v.help.textContent="先点选右侧功能区，\n再在左侧选择对应功能。\n按住八卦图标可以进行拖动。\n双击八卦图标置顶，\n再次双击取消。";function update(){v.title.textContent=(active<4?'内圈':active<10?'中圈':'外圈')+' · 位置'+(active+1);v.select.replaceChildren();const opts=fwOptions();if(!opts.some(x=>x[0]===fw.slots[active]))opts.push([fw.slots[active],'已移除的配置']);for(const [id,name]of opts){const o=el('option',name,v.select);o.value=id;}v.select.value=fw.slots[active];}function draw(){v.stage.replaceChildren();fwDraw(v.stage,i=>{active=i;update();},-1,false);}v.select.onchange=()=>{fw.slots[active]=v.select.value;fwSave();draw();};v.range.oninput=()=>{fw.size=Number(v.range.value);v.percent.textContent=v.range.value+'%';fwSave();const svg=v.stage.querySelector('svg');svg.setAttribute('width',380*fw.size/100);svg.setAttribute('height',380*fw.size/100);};update();draw();}
